package com.bank.arraylist;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ArrayListInternalsTest {

    // Helper: get internal array capacity via reflection
    private int getCapacity(ArrayList<?> list) throws Exception {
        Field field = ArrayList.class.getDeclaredField("elementData");
        field.setAccessible(true);
        return ((Object[]) field.get(list)).length;
    }

    @Test
    void defaultCapacity_becomens10OnFirstAdd() throws Exception {
        ArrayList<String> list = new ArrayList<>();
        // Before first add: capacity is 0 (lazy init in modern JDK)
        list.add("SAV2001");
        assertThat(getCapacity(list)).isEqualTo(10);  // first add → capacity 10!
    }

    @Test
    void growth_1point5x() throws Exception {
        ArrayList<String> list = new ArrayList<>();
        for (int i = 0; i < 11; i++) list.add("ACC-" + i);
        // 10 elements: capacity 10. 11th element triggers grow!
        assertThat(getCapacity(list)).isEqualTo(15);  // 10 * 1.5 = 15!

        for (int i = 11; i < 16; i++) list.add("ACC-" + i);
        assertThat(getCapacity(list)).isEqualTo(22);  // 15 * 1.5 ≈ 22!
    }

    @Test
    void initialCapacity_avoidsResize() throws Exception {
        ArrayList<String> list = new ArrayList<>(100);
        assertThat(getCapacity(list)).isEqualTo(100);
        for (int i = 0; i < 100; i++) list.add("ACC-" + i);
        assertThat(getCapacity(list)).isEqualTo(100);  // no resize needed!
    }

    @Test
    void trimToSize_reclaimsMemory() throws Exception {
        ArrayList<String> list = new ArrayList<>(1000);
        list.add("SAV2001");
        list.add("CUR3001");
        assertThat(getCapacity(list)).isEqualTo(1000);  // 998 slots wasted!

        list.trimToSize();
        assertThat(getCapacity(list)).isEqualTo(2);  // trimmed to actual size!
    }

    @Test
    void sizeVsCapacity() throws Exception {
        ArrayList<String> list = new ArrayList<>(50);
        list.add("A");
        list.add("B");
        assertThat(list.size()).isEqualTo(2);          // 2 elements
        assertThat(getCapacity(list)).isEqualTo(50);   // capacity still 50!
        // size() ≠ capacity!
    }

    @Test
    void performance_preAllocatedVsDefault() {
        int n = 500_000;

        // Without initial capacity (many resizes):
        long t1 = System.nanoTime();
        List<Integer> bad = new ArrayList<>();
        for (int i = 0; i < n; i++) bad.add(i);
        long badMs = (System.nanoTime() - t1) / 1_000_000;

        // With initial capacity (zero resizes):
        long t2 = System.nanoTime();
        List<Integer> good = new ArrayList<>(n);
        for (int i = 0; i < n; i++) good.add(i);
        long goodMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("Default: " + badMs + "ms, PreAllocated: " + goodMs + "ms");
        // PreAllocated is typically faster (fewer GC, zero array copies)
    }
}
