  class ArrayList<E> implements List<E>, RandomAccess {
    transient Object[] elementData;   // backing array
    private int size;                 // # elements (API-visible)
    // capacity = elementData.length (internal, not exposed)
    public ArrayList(int initialCapacity) {
      elementData = new Object[initialCapacity];  // pre-alloc
    }
    public E get(int i) {
      Objects.checkIndex(i, size);
      return (E) elementData[i];       // O(1) direct index
    }
    public boolean add(E e) { ... ensureCapacity ... }  // amortized O(1)
    public void trimToSize() {         // capacity → size
      elementData = Arrays.copyOf(elementData, size);
    }
  }
